var n=[{title:`Mecánica por encima de la cabeza`,text:`Empieza desde una base estable de pie o sentado. Mantén las costillas más o menos apiladas sobre la pelvis, tensa el tronco y empuja hacia arriba siguiendo una trayectoria cómoda para que los brazos terminen sobre la cabeza sin una gran inclinación hacia atrás. Los omóplatos giran normalmente hacia arriba cuando los brazos suben, e intentar fijarlos durante todo el levantamiento puede estorbar ese movimiento.`},{title:`Movilidad y diferencias individuales`,text:`Llegar por encima de la cabeza requiere suficiente movimiento del hombro y, normalmente, algo de ayuda de la parte alta de la espalda. La anatomía del hombro y los ángulos de agarre cómodos varían de una persona a otra. Si el press con barra recta resulta incómodo, quizá te convenga más un press con mancuernas con agarre neutro, un press landmine o un rango más corto por encima de la cabeza. Un dolor agudo significa que debes parar, así que no intentes forzar el estiramiento a través de él.`},{title:`Opciones con el peso corporal`,text:`Una flexión en pica coloca las caderas altas, de modo que los hombros asumen más carga. Una flexión en pica con los pies elevados puede ser más difícil y requiere más equilibrio y espacio. Para quienes empiezan, un press ligero de pie con mancuernas suele ser más sencillo y más fácil de ajustar que una variante difícil con el peso corporal.`},{title:`Problemas de técnica comunes`,text:`Un gran arco en la zona lumbar, empujar el peso muy por delante de ti y apresurar repeticiones inestables suelen indicar que la carga es demasiado pesada o que tu control es limitado. Reduce el peso, practica la trayectoria y mantén las piernas fuera de un press estricto. El push press es un ejercicio distinto que añade a propósito el impulso de las piernas.`},{title:`Cómo usar TrainUp`,text:`Tu plan solo incluye ejercicios por encima de la cabeza cuando tu equipamiento y la altura del techo indicada en Perfil dejan espacio suficiente. También ajusta los ejercicios a tu coordinación. Si unos hombros sensibles o la carga sobre la columna hacen que los press estándar por encima de la cabeza no te convengan, añade una limitación para esa zona del cuerpo en Perfil y el plan elegirá opciones menos exigentes.`}];var s=[{label:`Biblioteca de ejercicios de ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: técnica del entrenamiento con pesas (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`NSCA: seguridad y fundamentos del entrenamiento de fuerza`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`}];var i={sections:n,sources:s};export{i as default,n as sections,s as sources};